// Read-only, counts only: what happens after a $5 buy click (since the Nov 7 one-tap checkout).
import { sql } from "~/db";
const s = sql();
const out = async (label: string, p: Promise<unknown>) => { try { console.log(label, JSON.stringify(await p)); } catch (e) { console.log(label, "ERR", (e as Error).message.slice(0, 140)); } };
await out("checkout events by day", s`SELECT created_at::date AS day, event_name, label, COUNT(*)::int AS n, COUNT(DISTINCT visitor_id)::int AS v FROM funnel_events WHERE created_at > '2026-11-07' AND (event_name LIKE 'plan_checkout%' OR event_name LIKE 'checkout%' OR event_name IN ('bid_lock_starter_click','unlock_sheet_open','unlock_sheet_continue','starter_pass_purchased','purchase_completed')) GROUP BY 1, 2, 3 ORDER BY 1, 2`);
await out("per visitor: started vs redirected (since Nov 7)", s`SELECT COUNT(*)::int AS started_visitors, COUNT(*) FILTER (WHERE red)::int AS redirected, COUNT(*) FILTER (WHERE NOT red AND signin)::int AS sent_to_signin, COUNT(*) FILTER (WHERE NOT red AND failed)::int AS failed, COUNT(*) FILTER (WHERE NOT red AND NOT signin AND NOT failed)::int AS no_followup FROM (SELECT visitor_id, BOOL_OR(event_name='plan_checkout_redirected') AS red, BOOL_OR(event_name='plan_checkout_signin_required') AS signin, BOOL_OR(event_name='plan_checkout_failed') AS failed FROM funnel_events WHERE created_at > '2026-11-07' AND event_name LIKE 'plan_checkout%' GROUP BY visitor_id HAVING BOOL_OR(event_name='plan_checkout_started')) t`);
await out("stripe sessions (table)", s`SELECT status, COUNT(*)::int FROM stripe_checkout_sessions WHERE created_at > '2026-11-07' GROUP BY 1`);
await out("new paid users since Nov 7", s`SELECT plan_tier, subscription_status, COUNT(*)::int FROM users WHERE updated_at > '2026-11-07' AND (plan_tier IS NOT NULL) GROUP BY 1, 2`);
